package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class YouTubeProtectionTest {
 @Test public void dedicatedAdvertisingHostsAndTheirSubdomains(){for(String host:new String[]{"doubleclick.net","googleads.g.doubleclick.net","pagead2.googlesyndication.com","www.googleadservices.com","securepubads.g.doubleclick.net","googletagservices.com","adservice.google.com","adservice.google.com.br","DOUBLECLICK.NET."})assertTrue(host,YouTubeProtection.blocks("https://"+host+"/pagead?id=1",false));}
 @Test public void neverBlocksTheMainDocumentOrVideoAndSearchResources(){for(String url:new String[]{"https://m.youtube.com/watch?v=abc&ads=1","https://m.youtube.com/results?search_query=doubleclick.net","https://www.youtube.com/youtubei/v1/player","https://youtubei.googleapis.com/youtubei/v1/player","https://rr1---sn-a.googlevideo.com/videoplayback?ad=1","https://i.ytimg.com/vi/abc/default.jpg"})assertFalse(url,YouTubeProtection.blocks(url,false));assertFalse(YouTubeProtection.blocks("https://doubleclick.net/ad",true));}
 @Test public void domainBoundariesAndCredentialsCannotTriggerRule(){for(String url:new String[]{"https://doubleclick.net.evil.test/ad","https://notdoubleclick.net/ad","https://example.org/doubleclick.net","https://example.org/?host=doubleclick.net","https://doubleclick.net@example.org/ad","https://user@doubleclick.net/ad","file:///doubleclick.net","data:text/plain,doubleclick.net","not a url","https://[invalid/"})assertFalse(url,YouTubeProtection.blocks(url,false));assertFalse(YouTubeProtection.blocks(null,false));}
 @Test public void cosmeticRulesHaveNoPlayerOrSkipButtonSelectors(){String script=YouTubeProtection.cosmeticScript();assertTrue(script.contains("ytm-ad-slot-renderer"));for(String forbidden:new String[]{"MutationObserver","setInterval","setTimeout","fetch(","XMLHttpRequest","ad-showing","ytp-ad-skip-button","video{","currentTime","playbackRate"})assertFalse(forbidden,script.contains(forbidden));}
}
